/bin/bash -lc "python - <<'PY'
import os,sys,platform,tempfile,json,shutil,subprocess,importlib.metadata,urllib.request,urllib.error
r={'scope':'ChatGPT Work cloud environment inspection only','execution_tool':'functions.exec -> tools.exec_command','checks':{}}
c=r['checks']
c['platform']={'status':'passed','os':platform.system(),'release':platform.release(),'architecture':platform.machine(),'python':sys.version.split()[0]}
c['directories']={'status':'passed','cwd':os.getcwd(),'temporary_directory':tempfile.gettempdir()}
try:
 with tempfile.NamedTemporaryFile(mode='w+',prefix='map-toolkit-env-',delete=True) as f:
  f.write('map-toolkit-environment-probe');f.flush();f.seek(0)
  ok=f.read()=='map-toolkit-environment-probe'
 c['file_read_write']={'status':'passed' if ok else 'failed','location':tempfile.gettempdir(),'readback_matches':ok,'temporary_file_removed':not os.path.exists(f.name)}
except Exception as e:c['file_read_write']={'status':'failed','error_type':type(e).__name__}
try:
 p=subprocess.run(['node','--version'],capture_output=True,text=True,timeout=10)
 c['node']={'status':'passed' if p.returncode==0 else 'failed','version':p.stdout.strip(),'exit_code':p.returncode}
except Exception as e:c['node']={'status':'unavailable','error_type':type(e).__name__}
for name,module in [('Pillow','PIL'),('PyMuPDF','pymupdf')]:
 try:
  __import__(module)
  c[name]={'status':'passed','installed':True,'version':importlib.metadata.version(name)}
 except Exception as e:c[name]={'status':'unavailable','installed':False,'error_type':type(e).__name__}
for name,url in [('npm_https','https://registry.npmjs.org/'),('pypi_https','https://pypi.org/simple/')]:
 try:
  req=urllib.request.Request(url,method='GET',headers={'User-Agent':'environment-readonly-probe/1.0'})
  with urllib.request.urlopen(req,timeout=15) as response:
   sample=response.read(128)
   c[name]={'status':'passed','url':url,'http_status':response.status,'bytes_read':len(sample)}
 except Exception as e:
  c[name]={'status':'unavailable','url':url,'error_type':type(e).__name__,'reason':str(e)[:250]}
try:
 mem={}
 with open('/proc/meminfo') as f:
  for line in f:
   k,v=line.split(':',1)
   if k in ('MemTotal','MemAvailable'):mem[k+'_bytes']=int(v.split()[0])*1024
 limits={}
 for key,path in [('memory_max','/sys/fs/cgroup/memory.max'),('memory_current','/sys/fs/cgroup/memory.current')]:
  if os.path.isfile(path):
   with open(path) as f:limits[key]=f.read().strip()
 c['memory']={'status':'passed','host_observed':mem,'cgroup_observed':limits,'note':'Host memory may exceed process/container entitlement.'}
except Exception as e:c['memory']={'status':'unavailable','error_type':type(e).__name__}
d=shutil.disk_usage(os.getcwd())
c['disk']={'status':'passed','path':os.getcwd(),'total_bytes':d.total,'free_bytes':d.free,'used_bytes':d.used}
r['verdict']='passed' if all(v['status']=='passed' for v in c.values()) else 'unavailable' if any(v['status']=='unavailable' for v in c.values()) else 'failed'
r['limitations']=['No packages installed; registry GET only does not establish package installation feasibility.','No map analysis, plugin registration, mobile support, or Map Toolkit runtime validation performed.','Resource observations are point-in-time and may reflect shared host resources.']
with open('environment.json','w') as f:json.dump(r,f,ensure_ascii=False,indent=2)
print(json.dumps(r,ensure_ascii=False,indent=2))
PY"

